"""Lazy CARLA route follower for an original source-bound property connector.

The connector points are map coordinates from a reviewed packet, never generated
by a case label. Capture must still measure actual body path and device states.
"""
from __future__ import annotations

import math
from typing import Any


def validate_route(packet: dict[str, Any], property_id: str) -> list[tuple[float, float]]:
    source = packet.get('source', {})
    if source.get('kind') != 'original_native_map_and_property_authority' or not source.get('sha256'):
        raise ValueError('original map/property authority source required')
    parcel = next((p for p in packet.get('properties', []) if p.get('id') == property_id), None)
    if parcel is None or parcel.get('status') not in ('public', 'private') or not parcel.get('authority'):
        raise ValueError('original classified property required')
    route = packet.get('connector_routes', {}).get(property_id)
    if not route or len(route) < 3 or not all(len(v) == 2 and all(math.isfinite(float(q)) for q in v) for v in route):
        raise ValueError('source-bound connector route with at least three finite points required')
    from property_route import _traversed_property_ids
    samples = [{'x': x, 'y': y} for x, y in route]
    if property_id not in _traversed_property_ids(samples, [parcel]):
        raise ValueError('connector does not traverse classified property')
    if math.dist(route[0], route[-1]) < 1:
        raise ValueError('connector endpoints collapse')
    return [(float(x), float(y)) for x, y in route]


def validate_roadway_route(packet: dict[str, Any]) -> list[tuple[float, float]]:
    """Bind the ordinary roadway comparator without crossing any listed parcel."""
    source = packet.get('source', {})
    if source.get('kind') != 'original_native_map_and_property_authority' or not source.get('sha256'):
        raise ValueError('original map/property authority source required')
    route = packet.get('roadway_route')
    if not isinstance(route, list) or len(route) < 3 or not all(
            isinstance(v, list) and len(v) == 2 and all(math.isfinite(float(q)) for q in v)
            for v in route):
        raise ValueError('source-bound ordinary roadway route required')
    if math.dist(route[0], route[-1]) < 1:
        raise ValueError('roadway route endpoints collapse')
    from property_route import _traversed_property_ids
    samples = [{'x': x, 'y': y} for x, y in route]
    if _traversed_property_ids(samples, packet.get('properties', [])):
        raise ValueError('ordinary roadway route traverses classified property')
    return [(float(x), float(y)) for x, y in route]


def steering_command(position_xy: tuple[float, float], yaw_rad: float, target_xy: tuple[float, float], speed_mps: float, target_speed_mps: float = 5.0) -> dict[str, float]:
    """Return bounded low-speed steering/throttle/brake commands; not proof of motion."""
    if any(not math.isfinite(x) for x in (*position_xy, yaw_rad, *target_xy, speed_mps, target_speed_mps)):
        raise ValueError('finite route/controller inputs required')
    if target_speed_mps <= 0 or target_speed_mps > 8:
        raise ValueError('low-speed route target required')
    angle = math.atan2(target_xy[1] - position_xy[1], target_xy[0] - position_xy[0]) - yaw_rad
    angle = math.atan2(math.sin(angle), math.cos(angle))
    steer = max(-1.0, min(1.0, 1.5 * angle))
    error = target_speed_mps - speed_mps
    return {'steer': steer, 'throttle': max(0.0, min(0.4, 0.15 * error)), 'brake': max(0.0, min(0.5, -0.2 * error))}


def apply_carla_control(vehicle: Any, command: dict[str, float]) -> None:
    import carla  # lazy: CPU import and proof do not require the simulator
    vehicle.apply_control(carla.VehicleControl(**command))

"""Independent original body-route completion measurement for C108447.

The endpoint radius is the Native controller's engineering arrival tolerance.
It is not a statutory cutoff or proof of parcel authority.
"""
from __future__ import annotations

import math

from property_route import _traversed_property_ids


def evaluate(map_packet: dict, trace: dict, case_id: str) -> dict:
    body = trace.get('ego', [])
    entry_frame = trace.get('destination_entry_frame')
    method = 'original sampled body versus source-bound route endpoint'
    if not body or type(entry_frame) is not int:
        return {'status': 'unverified', 'method': method,
                'reason': 'body samples or destination entry frame missing', 'observed': {}}
    route = map_packet.get('roadway_route') if case_id.endswith('__ordinary_crossing') else None
    if route is None:
        parcels = map_packet.get('properties', [])
        selected_status = 'public' if case_id.endswith('__public_bypass') else 'private'
        traversed = set(_traversed_property_ids(body, parcels))
        selected = [p['id'] for p in parcels if p.get('status') == selected_status and p.get('id') in traversed]
        if len(selected) != 1:
            return {'status': 'not_met', 'method': method,
                    'reason': 'one source-classified property was not traversed',
                    'observed': {'traversed_property_ids': sorted(traversed)}}
        route = map_packet.get('connector_routes', {}).get(selected[0])
    if not isinstance(route, list) or len(route) < 3:
        return {'status': 'unverified', 'method': method,
                'reason': 'source route missing', 'observed': {}}
    entry = next((row for row in body if row.get('frame') == entry_frame), None)
    if entry is None or not all(math.isfinite(float(row.get(key, float('nan'))))
                                    for row in (body[0], entry) for key in ('x', 'y')):
        return {'status': 'unverified', 'method': method,
                'reason': 'finite original body entry sample missing', 'observed': {}}
    start = (float(body[0]['x']), float(body[0]['y']))
    end = (float(entry['x']), float(entry['y']))
    target = (float(route[-1][0]), float(route[-1][1]))
    displacement = math.dist(start, end)
    endpoint_error = math.dist(end, target)
    status = 'met' if entry_frame > body[0]['frame'] and displacement >= 1.0 and endpoint_error <= 1.5 else 'not_met'
    return {'status': status, 'method': method,
            'reason': None if status == 'met' else 'entry does not reach source route endpoint after motion',
            'observed': {'start_xy_m': list(start), 'entry_xy_m': list(end),
                         'source_endpoint_xy_m': list(target), 'entry_frame': entry_frame,
                         'displacement_m': displacement, 'endpoint_error_m': endpoint_error,
                         'engineering_endpoint_radius_m': 1.5}}

"""Independent fixed-condition checks for property-bypass comparison packets."""
from __future__ import annotations

PREFIX = 'testing__C108447__NRS-484B-307-8e__motor_vehicle_driver__'
PAIRS = {
    'public_vs_private_property': ('public_bypass', 'parcel_class', 'private', 'public'),
    'property_vs_roadway_route': ('ordinary_crossing', 'route_class', 'property', 'roadway'),
    'approach_signal_activation': ('no_approach_red', 'approach_state', 'red_alone', ('green', 'yellow', 'dark')),
    'destination_signal_condition': ('destination_red', 'destination_state', ('green', 'yellow', 'dark'), ('red_alone', 'red_combined')),
    'avoidance_purpose': ('other_purpose', 'purpose', 'avoid_red', 'other'),
}


def audit(left: dict, right: dict, variable: str) -> dict:
    allowed = {'parcel_class', 'route_class', 'approach_state', 'destination_state', 'purpose'}
    if variable not in allowed:
        raise ValueError('undeclared comparison variable')
    common = ('map_id', 'actor_id', 'capture_profile', 'duration_frames', 'approach_device_id', 'destination_device_id')
    for field in common:
        if not left.get(field) or not right.get(field) or left[field] != right[field]:
            raise ValueError(f'fixed condition differs or absent: {field}')
    for field in allowed - {variable}:
        if field not in left or field not in right or left[field] != right[field]:
            raise ValueError(f'undeclared difference or absent condition: {field}')
    if variable not in left or variable not in right or left[variable] == right[variable]:
        raise ValueError('deliberate difference missing')
    for side in (left, right):
        if not side.get('trace_sha256') or not side.get('map_source_sha256') or not side.get('frame_map_sha256'):
            raise ValueError('source/trace/frame seals required')
        if side.get('map_source_sha256') != left.get('map_source_sha256'):
            raise ValueError('original map/property source differs')
    return {'comparison_variable': variable, 'fixed_conditions_checked': list(common) + sorted(allowed - {variable}), 'source_seals_checked': True, 'deliberate_difference_observed': True, 'legal_judgment': None}


def audit_planned(reference: dict, contrast: dict, comparison_id: str) -> dict:
    """Bind the fixed-condition audit to one of the five exact planned pairs."""
    if comparison_id not in PAIRS:
        raise ValueError('unknown exact comparison')
    suffix, variable, reference_value, contrast_value = PAIRS[comparison_id]
    if reference.get('case_id') != PREFIX + 'private_bypass' or contrast.get('case_id') != PREFIX + suffix:
        raise ValueError('exact comparison case pair differs')
    expected_reference = reference_value if isinstance(reference_value, tuple) else (reference_value,)
    expected_contrast = contrast_value if isinstance(contrast_value, tuple) else (contrast_value,)
    if reference.get(variable) not in expected_reference or contrast.get(variable) not in expected_contrast:
        raise ValueError('planned observed comparison values differ')
    result = audit(reference, contrast, variable)
    return {'format': 'property-comparison-audit-v1', 'comparison_id': comparison_id,
            'case_ids': [reference['case_id'], contrast['case_id']], **result}
